  const {token,bid} = login.authentication;
  const h = {Authorization:`Bearer ${token}`};
  const prods = await (await r.get('http://localhost:3000/rest/products/search?q=Eggfruit')).json();
  const a = await r.post('http://localhost:3000/api/Addresss',{headers:h,data:{country:'Ukraine',fullName:'Test Customer',mobileNum:501234567,zipCode:'01001',streetAddress:'1 Khreshchatyk Street',city:'Kyiv',state:'Kyiv'}});
  const c = await r.post('http://localhost:3000/api/Cards',{headers:h,data:{fullName:'Test Customer',cardNum:4111111111111111,expMonth:12,expYear:2090}});
  const bi = await r.post('http://localhost:3000/api/BasketItems',{headers:h,data:{ProductId:prods.data[0].id,BasketId:bid,quantity:2}});
  const w = await r.put('http://localhost:3000/rest/wallet/balance',{headers:h,data:{balance:5}});
  await page.evaluate(([t,b])=>{localStorage.setItem('token',t);sessionStorage.setItem('bid',String(b));},[token,bid]);
  await page.context().addCookies([{name:'token',value:token,domain:'localhost',path:'/'}]);
  globalThis.__probe={email,password,token,bid};
  return {u:u.status(), u2: await u.json(), prods:prods.data.map(p=>({id:p.id,name:p.name,price:p.price})), a:a.status(), aj: await a.json(), c:c.status(), cj: await c.json(), bi:bi.status(), bij: await bi.json(), w:w.status(), wj: await w.text()};
}

