await (async (page) => {
  const token = await page.evaluate(()=>localStorage.getItem('token')); const h={Authorization:`Bearer ${token}`};
  const w = await page.request.put('http://localhost:3000/rest/wallet/balance',{headers:h,data:{balance:5,paymentId:7}});
  const g = await page.request.get('http://localhost:3000/rest/wallet/balance',{headers:h});
  await page.goto('http://localhost:3000/#/basket');
  await page.getByText('Total Price').waitFor();
  await page.waitForTimeout(1000);
  return {w:w.status(), wt: await w.text(), g: await g.text(), html: (await page.locator('app-basket').innerHTML()).replace(/<!--.*?-->/g,'').replace(/ _ngcontent-[^=]+=""/g,'').slice(0,7000), nav: (await page.locator('app-navbar').innerHTML()).replace(/<!--.*?-->/g,'').replace(/ _ngcontent-[^=]+=""/g,'').slice(0,5000)};
})(page);
```
