  await page.locator('button',{hasText:'Continue'}).click();
  await page.getByRole('row',{name:/Standard Delivery/}).getByRole('radio').click();
  await page.locator('button',{hasText:'Continue'}).click();
  await page.getByText('My Payment Options').waitFor(); await page.waitForTimeout(1200);
  const html = (await page.locator('app-payment').innerHTML()).replace(/<!--.*?-->/g,'').replace(/ _ngcontent-[^=]+=""/g,'').replace(/<svg.*?<\/svg>/g,'').replace(/ class="[^"]*"/g,'');
  const i = html.indexOf('Wallet Balance'); out.walletHtml = html.slice(i-400, i+900);
  await page.getByRole('button',{name:/Pay 8.99/}).click();
  await page.waitForURL(/order-summary/); await page.waitForTimeout(1200);
  out.summary = await page.locator('app-order-summary').innerText();
  await page.getByRole('button',{name:'Complete your purchase'}).click();
  await page.waitForURL(/order-completion/); await page.waitForTimeout(1500);
  const ch = (await page.locator('app-order-completion').innerHTML()).replace(/<!--.*?-->/g,'').replace(/ _ngcontent-[^=]+=""/g,'').replace(/<svg.*?<\/svg>/g,'').replace(/ class="[^"]*"/g,'').replace(/ mat-ripple[^ >]*/g,'');
  const j = ch.indexOf('<table'); out.completionTable = ch.slice(j, j+4000);
  const bal = await (await r.get(B+'/rest/wallet/balance',{headers:h})).json(); out.bal = bal;
  return out;
}

