import { encode } from 'z85';

/**
 * Juice Shop coupon codes: the Z85 encoding of `<MMM><YY>-<NN>` (test-cases/README.md).
 * The server accepts a coupon only in the month it names, in the local time of the machine.
 */
const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'] as const;

function couponText(date: Date, discountPercent: number): string {
  const month = MONTHS[date.getMonth()];
  const year = String(date.getFullYear()).slice(-2);
  const discount = String(discountPercent).padStart(2, '0');
  return `${month}${year}-${discount}`;
}

function encodeCoupon(text: string): string {
  const code = encode(text);
  if (!code) {
    throw new Error(`z85 cannot encode the coupon text "${text}"`);
  }
  return code;
}

export class CouponHelper {
  static currentMonthCoupon(discountPercent: number): string {
    return encodeCoupon(couponText(new Date(), discountPercent));
  }

  static previousMonthCoupon(discountPercent: number): string {
    const now = new Date();
    const previousMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    return encodeCoupon(couponText(previousMonth, discountPercent));
  }
}

