import { BaseApiClient } from '@/core/api/base-api-client';
import { API_ROUTES } from '@/utils/constants/routes';
import type { BasketLine, Customer } from '@/utils/types/shop';

const HTTP_OK = 200;

interface ProductSearchResponse {
  data: { id: number; name: string }[];
}

export class BasketApiClient extends BaseApiClient {
  async findProductId(productName: string): Promise<number> {
    const response = await this.request.get(API_ROUTES.productSearch, { params: { q: productName } });
    await this.expectStatus(response, HTTP_OK, `Search product ${productName}`);
    const { data } = (await response.json()) as ProductSearchResponse;
    const product = data.find((item) => item.name === productName);
    if (!product) {
      throw new Error(`Product "${productName}" is not in the catalog`);
    }
    return product.id;
  }

  async addLine(customer: Customer, line: BasketLine): Promise<void> {
    const productId = await this.findProductId(line.product.name);
    const response = await this.request.post(API_ROUTES.basketItems, {
      headers: this.authHeaders(customer),
      data: { ProductId: productId, BasketId: customer.basketId, quantity: line.quantity },
    });
    await this.expectStatus(response, HTTP_OK, `Add ${line.quantity} x ${line.product.name} to the basket`);
  }
}

