import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectContainText, expectStaysHidden, expectText, expectVisible } from '@/utils/assertions/ui-assertions';

const ACCOUNT_MENU_ITEMS = {
  login: 'Login',
  logout: 'Logout',
  ordersAndPayment: 'Orders & Payment',
  orderHistory: 'Order History',
  digitalWallet: 'Digital Wallet',
} as const;

/** The top bar of the shop: the account menu and the basket button with its counter. */
export class NavigationBar extends BasePage {
  private readonly accountButton: Locator;
  private readonly basketButton: Locator;
  private readonly basketCounter: Locator;
  private readonly accountMenu: Locator;

  constructor(page: Page) {
    super(page);
    this.accountButton = page.locator('#navbarAccount');
    this.basketButton = page.getByRole('button', { name: 'Show the shopping cart' });
    this.basketCounter = this.basketButton.locator('.fa-layers-counter');
    this.accountMenu = page.getByRole('menu').first();
  }

  private menuItem(text: string): Locator {
    return this.page.getByRole('menuitem').filter({ hasText: text });
  }

  async openAccountMenu(): Promise<void> {
    await this.accountButton.click();
    await expectVisible(this.accountMenu, 'Account menu');
  }

  async closeAccountMenu(): Promise<void> {
    await this.page.keyboard.press('Escape');
    await expectStaysHidden(this.accountMenu, 'Account menu');
  }

  async openOrderHistory(): Promise<void> {
    await this.openOrdersAndPaymentItem(ACCOUNT_MENU_ITEMS.orderHistory);
  }

  async openDigitalWallet(): Promise<void> {
    await this.openOrdersAndPaymentItem(ACCOUNT_MENU_ITEMS.digitalWallet);
  }

  private async openOrdersAndPaymentItem(itemText: string): Promise<void> {
    await this.openAccountMenu();
    await this.menuItem(ACCOUNT_MENU_ITEMS.ordersAndPayment).click();
    await this.menuItem(itemText).click();
  }

  async clickYourBasket(): Promise<void> {
    await this.basketButton.click();
  }

  async shouldSeeLoginMenuItem(): Promise<void> {
    await expectVisible(this.menuItem(ACCOUNT_MENU_ITEMS.login), `Account menu item "${ACCOUNT_MENU_ITEMS.login}"`);
  }

  async shouldSeeLogoutMenuItem(): Promise<void> {
    await expectVisible(this.menuItem(ACCOUNT_MENU_ITEMS.logout), `Account menu item "${ACCOUNT_MENU_ITEMS.logout}"`);
  }

  async shouldSeeEmailInAccountMenu(email: string): Promise<void> {
    await expectContainText(this.accountMenu, email, 'Account menu');
  }

  async shouldNotSeeEmailInAccountMenu(email: string): Promise<void> {
    await expectStaysHidden(this.accountMenu.getByText(email), `Email ${email} in the account menu`);
  }

  async shouldSeeBasketCount(count: number): Promise<void> {
    await expectText(this.basketCounter, String(count), 'Basket counter');
  }

  /** The counter shows `count` now and does not change during the hold window. */
  async shouldKeepBasketCount(count: number): Promise<void> {
    await this.shouldSeeBasketCount(count);
    const otherValue = this.basketCounter.filter({ hasNotText: new RegExp(`^\\s*${count}\\s*$`) });
    await expectStaysHidden(otherValue, `Basket counter with a value other than ${count}`);
  }
}

