import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_MESSAGES } from '@/utils/constants/shop-data';
import { expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import type { Customer } from '@/utils/types/shop';

const SESSION_KEYS = { token: 'token', basketId: 'bid' } as const;

export class LoginPage extends BasePage {
  private readonly heading: Locator;
  private readonly emailLabel: Locator;
  private readonly emailInput: Locator;
  private readonly passwordLabel: Locator;
  private readonly passwordInput: Locator;
  private readonly loginButton: Locator;
  private readonly errorMessage: Locator;

  constructor(page: Page) {
    super(page);
    this.heading = page.getByRole('heading', { name: 'Login', exact: true });
    this.emailLabel = page.locator('label[for="email"]');
    this.emailInput = page.locator('#email');
    this.passwordLabel = page.locator('label[for="password"]');
    this.passwordInput = page.locator('#password');
    this.loginButton = page.locator('#loginButton');
    this.errorMessage = page.locator('app-login .error');
  }

  async open(): Promise<void> {
    await this.page.goto(UI_ROUTES.login);
    await expectVisible(this.heading, 'Login page heading');
  }

  /** Real UI login. Use it only in tests of the login screen (auth-and-sessions.md). */
  async login(email: string, password: string): Promise<void> {
    await this.emailInput.fill(email);
    await this.passwordInput.fill(password);
    await this.loginButton.click();
  }

  /**
   * Puts the API session of the customer into the browser the way login.component.ts does:
   * the token in localStorage and in a cookie, the basket id in sessionStorage.
   */
  async authenticate(customer: Customer): Promise<void> {
    await this.page.goto(UI_ROUTES.home);
    await this.page.evaluate(
      ({ keys, token, basketId }) => {
        localStorage.setItem(keys.token, token);
        sessionStorage.setItem(keys.basketId, String(basketId));
      },
      { keys: SESSION_KEYS, token: customer.token, basketId: customer.basketId },
    );
    await this.page.context().addCookies([
      { name: SESSION_KEYS.token, value: customer.token, url: new URL(this.page.url()).origin },
    ]);
    await this.page.reload({ waitUntil: 'domcontentloaded' });
    await this.navbar.openAccountMenu();
    await this.navbar.shouldSeeEmailInAccountMenu(customer.email);
    await this.navbar.closeAccountMenu();
