import { BasePage } from '@/page-objects/base-page';
import { API_RESPONSE_MATCHERS, UI_ROUTES } from '@/utils/constants/routes';
import { expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import type { Product } from '@/utils/types/shop';

const SEARCH_URL = /\/#\/search/;

/** The product list `/#/search`. */
export class SearchPage extends BasePage {
  private readonly productCards: Locator;

  constructor(page: Page) {
    super(page);
    this.productCards = page.getByRole('article');
  }

  private productCard(product: Product): Locator {
    return this.productCards.filter({ hasText: product.name });
  }

  private addToBasketButton(product: Product): Locator {
    return this.productCard(product).getByRole('button', { name: 'Add to Basket' });
  }

  async open(): Promise<void> {
    await this.page.goto(UI_ROUTES.search);
    await this.shouldSeePage();
  }

  /** Waits for the server answer, so that the next click sees the updated basket. */
  async clickAddToBasket(product: Product): Promise<void> {
    await this.clickAndWaitForResponse(this.addToBasketButton(product), API_RESPONSE_MATCHERS.basketItems);
  }

  async shouldSeePage(): Promise<void> {
    await expect(this.page, 'The product list should be open').toHaveURL(SEARCH_URL);
    await expectVisible(this.productCards.first(), 'Product list');
  }

  async shouldSeeProduct(product: Product): Promise<void> {
    const card = this.productCard(product);
    await expectVisible(card, `Product card "${product.name}"`);
    await expectText(card.locator('.item-name'), product.name, `Name on the card of ${product.name}`);
    await expectText(card.locator('.item-price'), product.price, `Price on the card of ${product.name}`);
    await expectVisible(this.addToBasketButton(product), `"Add to Basket" button of ${product.name}`);
  }
}

