import { expect, type Locator } from '@playwright/test';
import { DateHelper } from '@/utils/helpers/date-helper';

/** How long an absence check watches the page before it passes (docs/core-beliefs.md, belief 3). */
export const ABSENCE_HOLD_MS = DateHelper.secondsToMs(2);

export async function expectVisible(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} should be visible`).toBeVisible();
}

export async function expectHidden(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} should be hidden`).toBeHidden();
}

export async function expectText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
  await expect(locator, `${description} should have the text "${text}"`).toHaveText(text);
}

export async function expectContainText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
  await expect(locator, `${description} should contain the text "${text}"`).toContainText(text);
}

export async function expectCount(locator: Locator, count: number, description: string): Promise<void> {
  await expect(locator, `${description} should have ${count} element(s)`).toHaveCount(count);
}

export async function expectEnabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} should be enabled`).toBeEnabled();
}

export async function expectDisabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} should be disabled`).toBeDisabled();
}

/**
 * Passes only when the locator stays absent for the whole hold window.
 * A retrying assertion would pass on the first absent read and miss a late appearance.
 */
export async function expectStaysHidden(
  locator: Locator,
  description: string,
  holdMs: number = ABSENCE_HOLD_MS,
): Promise<void> {
  const appeared = await locator
    .first()
    .waitFor({ state: 'visible', timeout: holdMs })
    .then(() => true)
    .catch(() => false);
  expect(appeared, `${description} should not appear within ${holdMs} ms`).toBe(false);
}

