import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectContainText, expectVisible } from '@/utils/assertions/ui-assertions';
import type { SavedAddress } from '@/utils/types/shop';

/** Checkout step `Select an address`. */
export class AddressSelectPage extends BasePage {
  private readonly heading: Locator;
  private readonly continueButton: Locator;

  constructor(page: Page) {
    super(page);
    this.heading = page.getByRole('heading', { name: 'Select an address' });
    this.continueButton = page.locator('app-address-select button', { hasText: 'Continue' });
  }

  private addressRow(address: SavedAddress): Locator {
    return this.page.locator('app-address-select mat-row').filter({ hasText: address.streetAddress });
  }

  async selectAddress(address: SavedAddress): Promise<void> {
    await this.addressRow(address).getByRole('radio').click();
  }

  async clickContinue(): Promise<void> {
    await this.continueButton.click();
  }

  async selectAddressAndContinue(address: SavedAddress): Promise<void> {
    await this.shouldSeePage();
    await this.selectAddress(address);
    await this.clickContinue();
  }

  async shouldSeePage(): Promise<void> {
    await expectVisible(this.heading, '"Select an address" heading');
  }

  async shouldSeeSavedAddress(address: SavedAddress): Promise<void> {
    const row = this.addressRow(address);
    await expectVisible(row, 'Saved address row');
    for (const part of [address.fullName, address.streetAddress, address.city, address.state, address.zipCode, address.country]) {
      await expectContainText(row, part, 'Saved address row');
    }
  }
}

