import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectText, expectVisible } from '@/utils/assertions/ui-assertions';

export interface DeliveryMethod {
  name: string;
  price: string;
}

/** Checkout step `Choose a delivery speed`. */
export class DeliveryMethodPage extends BasePage {
  private readonly heading: Locator;
  private readonly continueButton: Locator;

  constructor(page: Page) {
    super(page);
    this.heading = page.getByRole('heading', { name: 'Choose a delivery speed' });
    this.continueButton = page.locator('app-delivery-method button', { hasText: 'Continue' });
  }

  private methodRow(method: DeliveryMethod): Locator {
    return this.page.locator('app-delivery-method mat-row').filter({ hasText: method.name });
  }

  async selectDeliveryMethod(method: DeliveryMethod): Promise<void> {
    await this.methodRow(method).getByRole('radio').click();
  }

  async clickContinue(): Promise<void> {
    await this.continueButton.click();
  }

  async selectDeliveryMethodAndContinue(method: DeliveryMethod): Promise<void> {
    await this.shouldSeePage();
    await this.selectDeliveryMethod(method);
    await this.clickContinue();
  }

  async shouldSeePage(): Promise<void> {
    await expectVisible(this.heading, '"Choose a delivery speed" heading');
  }

  async shouldSeeDeliveryMethod(method: DeliveryMethod): Promise<void> {
    const row = this.methodRow(method);
    await expectVisible(row, `Delivery method "${method.name}"`);
    await expectText(row.getByRole('cell').nth(2), method.price, `Price of "${method.name}"`);
  }
}

