import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { CouponPanelComponent } from '@/page-objects/checkout/components/coupon-panel.component';
import { SavedCardsComponent } from '@/page-objects/checkout/components/saved-cards.component';
import { WalletPaymentComponent } from '@/page-objects/checkout/components/wallet-payment.component';
import { expectVisible } from '@/utils/assertions/ui-assertions';

/** Checkout step `My Payment Options`: saved cards, the wallet and the coupon panel. */
export class PaymentPage extends BasePage {
  private readonly heading: Locator;
  private readonly continueButton: Locator;
  private readonly savedCards: SavedCardsComponent;
  private readonly walletPayment: WalletPaymentComponent;
  private readonly couponPanel: CouponPanelComponent;

  constructor(page: Page) {
    super(page);
    this.heading = page.getByRole('heading', { name: 'My Payment Options' });
    this.continueButton = page.locator('app-payment button', { hasText: 'Continue' });
    this.savedCards = new SavedCardsComponent(page);
    this.walletPayment = new WalletPaymentComponent(page);
    this.couponPanel = new CouponPanelComponent(page);
  }

  async shouldSeePage(): Promise<void> {
    await expectVisible(this.heading, '"My Payment Options" heading');
  }

  async clickContinue(): Promise<void> {
    await this.continueButton.click();
  }

  async selectSavedCard(lastDigits: string): Promise<void> {
    await this.savedCards.selectCard(lastDigits);
  }

  async shouldSeeSavedCard(lastDigits: string, holderName: string): Promise<void> {
    await this.savedCards.shouldSeeCard(lastDigits, holderName);
  }

  async openCouponPanel(): Promise<void> {
    await this.couponPanel.openPanel();
  }

  async redeemCoupon(code: string): Promise<void> {
    await this.couponPanel.redeemCoupon(code);
  }

  async shouldSeeCouponPanel(): Promise<void> {
    await this.couponPanel.shouldSeePanel();
  }

  async shouldSeeCouponDiscount(percent: number): Promise<void> {
    await this.couponPanel.shouldSeeDiscountConfirmation(percent);
  }

  async shouldSeeInvalidCouponError(): Promise<void> {
    await this.couponPanel.shouldSeeInvalidCouponError();
  }

  async shouldNotSeeCouponDiscount(): Promise<void> {
    await this.couponPanel.shouldNotSeeDiscountConfirmation();
  }

  async clickPayWithWallet(amount: string): Promise<void> {
