import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_MESSAGES } from '@/utils/constants/shop-data';
import { expectText, expectTexts, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import type { BasketLine, OrderTotals } from '@/utils/types/shop';

const ORDER_COMPLETION_URL = /\/#\/order-completion\/[\w-]+$/;
const TOTAL_LABELS = ['Items', 'Delivery', 'Promotion', 'Total Price'];

/** The confirmation page `/#/order-completion/<order ID>`. */
export class OrderCompletionPage extends BasePage {
  private readonly heading: Locator;
  private readonly productRows: Locator;
  private readonly totalLabels: Locator;
  private readonly totalValues: Locator;

  constructor(page: Page) {
    super(page);
    this.heading = page.getByRole('heading', { name: UI_MESSAGES.orderThankYou });
    this.productRows = page.locator('app-order-completion mat-row');
    // The totals are two nested tables in the footer row: one with the labels, one with the values.
    const totalsCells = page.locator('app-order-completion mat-footer-row mat-footer-cell');
    this.totalLabels = totalsCells.filter({ hasText: TOTAL_LABELS[0] }).locator('td');
    this.totalValues = totalsCells.last().locator('td');
  }

  /** The order ID from the URL `/#/order-completion/<order ID>`. */
  readOrderId(): string {
    return this.page.url().split(UI_ROUTES.orderCompletion)[1];
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, ORDER_COMPLETION_URL, 'Order confirmation page');
    await expectVisible(this.heading, `"${UI_MESSAGES.orderThankYou}" heading`);
  }

  async shouldSeeProductLine(line: BasketLine): Promise<void> {
    const row = this.productRows.filter({ hasText: line.product.name });
    await expectVisible(row, `Confirmation row of ${line.product.name}`);
    await expectText(row.locator('.mat-column-quantity'), String(line.quantity), `Quantity of ${line.product.name}`);
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    await expectTexts(this.totalLabels, TOTAL_LABELS, 'Confirmation total labels');
    await expectTexts(
      this.totalValues,
      [totals.items, totals.delivery, totals.promotion, totals.total],
      'Confirmation total values',
    );
  }
}

