  private readonly title: Locator;
  private readonly orders: Locator;
  private readonly noOrdersMessage: Locator;

  constructor(page: Page) {
    super(page);
    this.title = page.locator('app-order-history mat-card-title', { hasText: 'Order History' });
    this.orders = page.locator('app-order-history .table-container');
    this.noOrdersMessage = page.locator('app-order-history').getByText(UI_MESSAGES.noOrdersYet);
  }

  private order(orderId?: string): Locator {
    return orderId ? this.orders.filter({ hasText: `#${orderId}` }) : this.orders;
  }

  private headingValue(order: Locator, label: string): Locator {
    return order.locator('.heading-row .col').filter({ hasText: label }).locator('div').last();
  }

  async shouldSeePage(): Promise<void> {
    await expectVisible(this.title, '"Order History" title');
  }

  async shouldSeeOrderCount(count: number): Promise<void> {
    await expectCount(this.orders, count, 'Orders in the history');
  }

  async shouldSeeNoOrders(): Promise<void> {
    await expectVisible(this.noOrdersMessage, `"${UI_MESSAGES.noOrdersYet}" message`);
    await expectCount(this.orders, 0, 'Orders in the history');
  }

  /** Without `orderId`, the history must hold exactly one order. */
  async shouldSeeOrderTotal(total: string, orderId?: string): Promise<void> {
    const order = this.order(orderId);
    await expectCount(order, 1, `Order ${orderId ?? ''} in the history`);
    await expectText(this.headingValue(order, 'Total Price'), total, `Total price of order ${orderId ?? ''}`);
  }

  async shouldSeeOrderBonus(bonus: number, orderId?: string): Promise<void> {
    const order = this.order(orderId);
    await expectCount(order, 1, `Order ${orderId ?? ''} in the history`);
    await expectText(this.headingValue(order, 'Bonus'), String(bonus), `Bonus of order ${orderId ?? ''}`);
  }

  async shouldSeeOrderProductLine(line: BasketLine, orderId?: string): Promise<void> {
    const row = this.order(orderId).locator('mat-row').filter({ hasText: line.product.name });
    await expectVisible(row, `Order row of ${line.product.name}`);
    await expectText(row.locator('.mat-column-quantity'), String(line.quantity), `Quantity of ${line.product.name}`);
  }
}

