/**
 * Test-data setup through the API: a new customer for each test, with an optional basket,
 * the saved address and card of test-cases/README.md, and a wallet balance.
 */
import { randomUUID } from 'node:crypto';
import type { ApiClients } from '@/core/api/api-clients';
import { SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/shop-data';
import type { BasketLine, Customer } from '@/utils/types/shop';

const EMAIL_DOMAIN = 'example.test';
const PASSWORD_PREFIX = 'Passw0rd!';
const UNIQUE_PART_LENGTH = 8;

export interface CheckoutReadyCustomer {
  customer: Customer;
  savedCardId: number;
}

export async function createCustomer(api: ApiClients): Promise<Customer> {
  const uniquePart = `${Date.now()}-${randomUUID().slice(0, UNIQUE_PART_LENGTH)}`;
  return api.customers.register(`autotest-${uniquePart}@${EMAIL_DOMAIN}`, `${PASSWORD_PREFIX}${uniquePart}`);
}

export async function fillBasket(api: ApiClients, customer: Customer, lines: BasketLine[]): Promise<void> {
  for (const line of lines) {
    await api.basket.addLine(customer, line);
  }
}

export async function createCustomerWithBasket(api: ApiClients, lines: BasketLine[]): Promise<Customer> {
  const customer = await createCustomer(api);
  await fillBasket(api, customer, lines);
  return customer;
}

/** A new customer with the saved address, the saved card and the given basket lines. */
export async function createCheckoutReadyCustomer(api: ApiClients, lines: BasketLine[]): Promise<CheckoutReadyCustomer> {
  const customer = await createCustomerWithBasket(api, lines);
  await api.paymentData.saveAddress(customer, SAVED_ADDRESS);
  const savedCardId = await api.paymentData.saveCard(customer, SAVED_CARD);
  return { customer, savedCardId };
}

/** Adds money to the wallet. The server takes it from the saved card. */
export async function topUpWallet(api: ApiClients, buyer: CheckoutReadyCustomer, amount: number): Promise<void> {
  await api.paymentData.topUpWallet(buyer.customer, buyer.savedCardId, amount);
}

