import { BaseApiClient } from '@/core/api/base-api-client';
import { API_ROUTES } from '@/utils/constants/routes';
import type { Customer } from '@/utils/types/shop';

const HTTP_CREATED = 201;
const HTTP_OK = 200;
const SECURITY_QUESTION_ID = 1;
const SECURITY_ANSWER = 'autotest';

interface LoginResponse {
  authentication: { token: string; bid: number; umail: string };
}

export class CustomerApiClient extends BaseApiClient {
  /** Registers a normal (not deluxe) customer and logs in to get the token and the basket id. */
  async register(email: string, password: string): Promise<Customer> {
    const response = await this.request.post(API_ROUTES.users, {
      data: {
        email,
        password,
        passwordRepeat: password,
        securityQuestion: { id: SECURITY_QUESTION_ID },
        securityAnswer: SECURITY_ANSWER,
      },
    });
    await this.expectStatus(response, HTTP_CREATED, `Register customer ${email}`);
    return this.login(email, password);
  }

  async login(email: string, password: string): Promise<Customer> {
    const response = await this.request.post(API_ROUTES.login, { data: { email, password } });
    await this.expectStatus(response, HTTP_OK, `Log in customer ${email}`);
    const { authentication } = (await response.json()) as LoginResponse;
    return { email, password, token: authentication.token, basketId: authentication.bid };
  }
}

