import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS, PURCHASE_LIMIT_PER_PRODUCT, UI_MESSAGES } from '@/utils/constants/shop-data';

const product = PRODUCTS.appleJuice;
const limitTotalPrice = '9.95¤';

test('Purchase limit for one product', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-04' },
}, async ({ customer: _customer, searchPage, basketPage }) => {
  await test.step('1. Open the product list and click "Add to Basket" on the product', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(product);
    await searchPage.toastMessages.shouldSeeMessage(UI_MESSAGES.placedIntoBasket(product.name));
    await searchPage.navbar.shouldSeeBasketCount(1);
  });

  await test.step('2. Open the basket and click plus until the quantity is the limit', async () => {
    await basketPage.open();
    await basketPage.increaseQuantityTo(product, PURCHASE_LIMIT_PER_PRODUCT, 1);
    await basketPage.shouldSeeQuantity(product, PURCHASE_LIMIT_PER_PRODUCT);
    await basketPage.shouldSeeTotalPrice(limitTotalPrice);
    await basketPage.toastMessages.shouldNotSeeErrorMessage();
  });

  await test.step('3. Click the plus button one more time', async () => {
    await basketPage.clickIncreaseQuantity(product);
    await basketPage.toastMessages.shouldSeeErrorMessage(UI_MESSAGES.purchaseLimit(PURCHASE_LIMIT_PER_PRODUCT));
  });

  await test.step('4. Read the basket', async () => {
    await basketPage.shouldKeepQuantity(product, PURCHASE_LIMIT_PER_PRODUCT);
    await basketPage.shouldSeeTotalPrice(limitTotalPrice);
    await basketPage.navbar.shouldSeeBasketCount(PURCHASE_LIMIT_PER_PRODUCT);
  });

  await test.step('5. Open the product list and click "Add to Basket" on the product', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(product);
    await searchPage.toastMessages.shouldSeeErrorMessage(UI_MESSAGES.purchaseLimit(PURCHASE_LIMIT_PER_PRODUCT));
    await searchPage.navbar.shouldKeepBasketCount(PURCHASE_LIMIT_PER_PRODUCT);
  });
});

