import { test } from '@/fixtures/pages.fixture';
import { createCheckoutReadyCustomer } from '@/tests/helpers/customer-setup';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import {
  COUPON_DISCOUNT_PERCENT,
  DELIVERY_METHODS,
  INVALID_COUPON_CODE,
  PRODUCTS,
  SAVED_ADDRESS,
  SAVED_CARD_LAST_DIGITS,
} from '@/utils/constants/shop-data';
import { CouponHelper } from '@/utils/helpers/coupon-helper';
import type { OrderTotals } from '@/utils/types/shop';

const basketLine = { product: PRODUCTS.eggfruitJuice, quantity: 2 };
const delivery = DELIVERY_METHODS.oneDay;
const expectedTotalsWithoutDiscount: OrderTotals = {
  items: '17.98¤',
  delivery: '0.99¤',
  promotion: '0.00¤',
  total: '18.97¤',
};

test('Invalid coupon and expired coupon', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.coupon],
  annotation: { type: 'test-case', description: 'TC-06' },
}, async ({ api, loginPage, basketPage, addressSelectPage, deliveryMethodPage, paymentPage, orderSummaryPage }) => {
  await test.step('Precondition: log in a new customer with a saved address, a saved card and the product in the basket', async () => {
    const { customer } = await createCheckoutReadyCustomer(api, [basketLine]);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the basket, click "Checkout", select the saved address and continue', async () => {
    await basketPage.open();
    await basketPage.clickCheckout();
    await addressSelectPage.selectAddressAndContinue(SAVED_ADDRESS);
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step('2. Select "One Day Delivery" and continue', async () => {
    await deliveryMethodPage.selectDeliveryMethod(delivery);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
  });

  await test.step('3. Redeem the invalid code', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(INVALID_COUPON_CODE);
    await paymentPage.shouldSeeInvalidCouponError();
    await paymentPage.shouldNotSeeCouponDiscount();
  });

  await test.step('4. Redeem the expired coupon of the previous month', async () => {
    await paymentPage.redeemCoupon(CouponHelper.previousMonthCoupon(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeInvalidCouponError();
    await paymentPage.shouldNotSeeCouponDiscount();
  });

  await test.step('5. Select the saved card and continue', async () => {
    await paymentPage.selectSavedCard(SAVED_CARD_LAST_DIGITS);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeTotals(expectedTotalsWithoutDiscount);
  });
