import { test } from '@/fixtures/pages.fixture';
import { createCheckoutReadyCustomer } from '@/tests/helpers/customer-setup';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import {
  COUPON_DISCOUNT_PERCENT,
  DELIVERY_METHODS,
  PRODUCTS,
  SAVED_ADDRESS,
  SAVED_CARD,
  SAVED_CARD_LAST_DIGITS,
} from '@/utils/constants/shop-data';
import { CouponHelper } from '@/utils/helpers/coupon-helper';
import { DateHelper } from '@/utils/helpers/date-helper';
import type { BasketLine, OrderTotals } from '@/utils/types/shop';

const lineA: BasketLine = { product: PRODUCTS.eggfruitJuice, quantity: 2 };
const lineB: BasketLine = { product: PRODUCTS.carrotJuice, quantity: 1 };
const delivery = DELIVERY_METHODS.oneDay;
const itemsTotal = '20.97¤';
const expectedTotals: OrderTotals = { items: itemsTotal, delivery: '0.99¤', promotion: '2.10¤', total: '19.86¤' };

test('Order with a card, from basket to order history', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.checkout],
  annotation: { type: 'test-case', description: 'TC-07' },
}, async ({
  api,
  loginPage,
  searchPage,
  basketPage,
  addressSelectPage,
  deliveryMethodPage,
  paymentPage,
  orderSummaryPage,
  orderCompletionPage,
  orderHistoryPage,
}) => {
  // Ten UI steps through the whole checkout do not fit into the default 30 seconds.
  test.setTimeout(DateHelper.minutesToMs(2));
  let orderId = '';

  await test.step('Precondition: log in a new customer with a saved address, a saved card and an empty basket', async () => {
    const { customer } = await createCheckoutReadyCustomer(api, []);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Add product A two times and product B one time from the product list', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(lineA.product);
    await searchPage.clickAddToBasket(lineA.product);
    await searchPage.clickAddToBasket(lineB.product);
    await searchPage.navbar.shouldSeeBasketCount(lineA.quantity + lineB.quantity);
  });

  await test.step('2. Open the basket', async () => {
    await basketPage.open();
    await basketPage.shouldSeeOnlyLines([lineA, lineB]);
    await basketPage.shouldSeeTotalPrice(itemsTotal);
  });

  await test.step('3. Click "Checkout", select the saved address and continue', async () => {
    await basketPage.clickCheckout();
    await addressSelectPage.selectAddressAndContinue(SAVED_ADDRESS);
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step('4. Select "One Day Delivery" and continue', async () => {
    await deliveryMethodPage.selectDeliveryMethod(delivery);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
  });

  await test.step('5. Redeem the coupon of the current month', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(CouponHelper.currentMonthCoupon(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeCouponDiscount(COUPON_DISCOUNT_PERCENT);
  });

  await test.step('6. Select the saved card and continue', async () => {
    await paymentPage.selectSavedCard(SAVED_CARD_LAST_DIGITS);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeDeliveryAddress(SAVED_ADDRESS);
    await orderSummaryPage.shouldSeePaymentCard(SAVED_CARD_LAST_DIGITS, SAVED_CARD.fullName);
    await orderSummaryPage.shouldSeeTotals(expectedTotals);
  });

  await test.step('7. Click "Place your order and pay"', async () => {
    await orderSummaryPage.clickPlaceOrderAndPay();
    await orderCompletionPage.shouldSeePage();
    orderId = orderCompletionPage.readOrderId();
  });

  await test.step('8. Read the order summary on the confirmation page', async () => {
    await orderCompletionPage.shouldSeeProductLine(lineA);
    await orderCompletionPage.shouldSeeProductLine(lineB);
    await orderCompletionPage.shouldSeeTotals(expectedTotals);
  });

  await test.step('9. Read the basket counter and open the basket', async () => {
    await orderCompletionPage.navbar.shouldSeeBasketCount(0);
    await basketPage.open();
    await basketPage.shouldSeeEmptyBasket();
    await basketPage.shouldSeeCheckoutDisabled();
  });

  await test.step('10. Open "Order History" from the account menu', async () => {
    await basketPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeOrderCount(1);
    await orderHistoryPage.shouldSeeOrderTotal(expectedTotals.total, orderId);
    await orderHistoryPage.shouldSeeOrderProductLine(lineA, orderId);
    await orderHistoryPage.shouldSeeOrderProductLine(lineB, orderId);
  });
});

