  api,
  loginPage,
  basketPage,
  addressSelectPage,
  deliveryMethodPage,
  paymentPage,
  orderSummaryPage,
  orderCompletionPage,
  orderHistoryPage,
  walletPage,
}) => {
  // Two checkout passes and four account pages do not fit into the default 30 seconds.
  test.setTimeout(DateHelper.minutesToMs(2));
  let buyer: CheckoutReadyCustomer;

  await test.step('Precondition: log in a new customer with a saved address, a saved card, the product in the basket and 5.00 in the wallet', async () => {
    buyer = await createCheckoutReadyCustomer(api, [basketLine]);
    await topUpWallet(api, buyer, firstTopUp);
    await loginPage.authenticate(buyer.customer);
  });

  await test.step('1. Open the basket, click "Checkout", select the saved address and continue', async () => {
    await basketPage.open();
    await basketPage.clickCheckout();
    await addressSelectPage.selectAddressAndContinue(SAVED_ADDRESS);
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step('2. Select "Standard Delivery" and continue', async () => {
    await deliveryMethodPage.selectDeliveryMethod(delivery);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(BALANCES.first);
    await paymentPage.shouldSeeWalletPayButton(orderTotal);
  });

  await test.step(`3. Read the button "Pay ${orderTotal}"`, async () => {
    await paymentPage.shouldSeeWalletPayButtonDisabled(orderTotal);
  });

  await test.step('4. Open "Order History" from the account menu', async () => {
    await paymentPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeNoOrders();
  });

  await test.step('5. Open "Digital Wallet" from the account menu', async () => {
    await orderHistoryPage.navbar.openDigitalWallet();
    await walletPage.shouldSeePage();
    await walletPage.shouldSeeBalance(BALANCES.first);
  });

  await test.step('Precondition: add 3.99 to the wallet with the saved card', async () => {
    await topUpWallet(api, buyer, secondTopUp);
  });

  await test.step('6. Go through checkout to the payment step with "Standard Delivery"', async () => {
    await basketPage.open();
    await basketPage.clickCheckout();
    await addressSelectPage.selectAddressAndContinue(SAVED_ADDRESS);
    await deliveryMethodPage.selectDeliveryMethodAndContinue(delivery);
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(BALANCES.equalToOrderTotal);
    await paymentPage.shouldSeeWalletPayButtonEnabled(orderTotal);
