import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectContainText, expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import type { OrderTotals, SavedAddress } from '@/utils/types/shop';

const ORDER_SUMMARY_URL = /\/#\/order-summary$/;
const TOTAL_LABELS = { items: 'Items', delivery: 'Delivery', promotion: 'Promotion', total: 'Total Price' } as const;

/** Checkout step `Order Summary`, before the order is placed. */
export class OrderSummaryPage extends BasePage {
  private readonly summaryTitle: Locator;
  private readonly deliveryAddressCard: Locator;
  private readonly paymentMethodCard: Locator;
  private readonly placeOrderButton: Locator;

  constructor(page: Page) {
    super(page);
    this.summaryTitle = page.locator('app-order-summary').getByText('Order Summary', { exact: true });
    this.deliveryAddressCard = page.locator('app-order-summary mat-card', { hasText: 'Delivery Address' }).last();
    this.paymentMethodCard = page.locator('app-order-summary mat-card', { hasText: 'Payment Method' }).last();
    this.placeOrderButton = page.getByRole('button', { name: 'Complete your purchase' });
  }

  private totalValue(label: string): Locator {
    return this.page.locator('app-order-summary tr').filter({ hasText: label }).locator('td').last();
  }

  async clickPlaceOrderAndPay(): Promise<void> {
    await expectText(this.placeOrderButton, 'Place your order and pay', 'Place order button');
    await this.placeOrderButton.click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, ORDER_SUMMARY_URL, 'Order summary page');
    await expectVisible(this.summaryTitle, '"Order Summary" title');
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    for (const key of Object.keys(TOTAL_LABELS) as (keyof OrderTotals)[]) {
      await expectText(this.totalValue(TOTAL_LABELS[key]), totals[key], `Order summary line "${TOTAL_LABELS[key]}"`);
    }
  }

  async shouldSeeTotalPrice(total: string): Promise<void> {
    await expectText(this.totalValue(TOTAL_LABELS.total), total, `Order summary line "${TOTAL_LABELS.total}"`);
  }

  async shouldSeeDeliveryAddress(address: SavedAddress): Promise<void> {
    for (const part of [address.fullName, address.streetAddress, address.city, address.zipCode, address.country]) {
      await expectContainText(this.deliveryAddressCard, part, 'Delivery address card');
    }
  }

  async shouldSeePaymentCard(lastDigits: string, holderName: string): Promise<void> {
    await expectContainText(this.paymentMethodCard, `Card ending in ${lastDigits}`, 'Payment method card');
    await expectContainText(this.paymentMethodCard, holderName, 'Payment method card');
  }

  async shouldSeePaymentMethod(method: string): Promise<void> {
    await expectContainText(this.paymentMethodCard, method, 'Payment method card');
  }
}

