1	import type { Locator, Page } from '@playwright/test';
2	import { BasePage } from '@/page-objects/base-page';
3	import { UI_ROUTES } from '@/utils/constants/routes';
4	import { UI_MESSAGES } from '@/utils/constants/shop-data';
5	import { expectText, expectVisible } from '@/utils/assertions/ui-assertions';
6	import type { Customer } from '@/utils/types/shop';
7	
8	const SESSION_KEYS = { token: 'token', basketId: 'bid' } as const;
9	
10	export class LoginPage extends BasePage {
11	  private readonly heading: Locator;
12	  private readonly emailLabel: Locator;
13	  private readonly emailInput: Locator;
14	  private readonly passwordLabel: Locator;
15	  private readonly passwordInput: Locator;
16	  private readonly loginButton: Locator;
17	  private readonly errorMessage: Locator;
18	
19	  constructor(page: Page) {
20	    super(page);
21	    this.heading = page.getByRole('heading', { name: 'Login', exact: true });
22	    this.emailLabel = page.locator('label[for="email"]');
23	    this.emailInput = page.locator('#email');
24	    this.passwordLabel = page.locator('label[for="password"]');
25	    this.passwordInput = page.locator('#password');
26	    this.loginButton = page.locator('#loginButton');
27	    this.errorMessage = page.locator('app-login .error');
28	  }
29	
30	  async open(): Promise<void> {
31	    await this.page.goto(UI_ROUTES.login);
32	    await expectVisible(this.heading, 'Login page heading');
33	  }
34	
35	  /** Real UI login. Use it only in tests of the login screen (auth-and-sessions.md). */
36	  async login(email: string, password: string): Promise<void> {
37	    await this.emailInput.fill(email);
38	    await this.passwordInput.fill(password);
39	    await this.loginButton.click();
40	  }
41	
42	  /**
43	   * Puts the API session of the customer into the browser the way login.component.ts does:
44	   * the token in localStorage and in a cookie, the basket id in sessionStorage.
45	   */
46	  async authenticate(customer: Customer): Promise<void> {
47	    await this.page.goto(UI_ROUTES.home);
48	    await this.page.evaluate(
49	      ({ keys, token, basketId }) => {
50	        localStorage.setItem(keys.token, token);
51	        sessionStorage.setItem(keys.basketId, String(basketId));
52	      },
53	      { keys: SESSION_KEYS, token: customer.token, basketId: customer.basketId },
54	    );
55	    await this.page.context().addCookies([
56	      { name: SESSION_KEYS.token, value: customer.token, url: new URL(this.page.url()).origin },
57	    ]);
58	    await this.page.reload({ waitUntil: 'domcontentloaded' });
59	    await this.navbar.openAccountMenu();
60	    await this.navbar.shouldSeeEmailInAccountMenu(customer.email);
61	    await this.navbar.closeAccountMenu();
62	  }
63	
64	  async shouldSeePage(): Promise<void> {
65	    await expectVisible(this.heading, 'Login page heading');
66	    await expectText(this.emailLabel, 'Email', 'Email field label');
67	    await expectVisible(this.emailInput, 'Email field');
68	    await expectText(this.passwordLabel, 'Password', 'Password field label');
69	    await expectVisible(this.passwordInput, 'Password field');
70	    await expectVisible(this.loginButton.getByText('Log in', { exact: true }), '"Log in" button');
71	  }
72	
73	  async shouldSeeInvalidCredentialsError(): Promise<void> {
74	    await expectText(this.errorMessage, UI_MESSAGES.invalidLogin, 'Login error message');
75	  }
76	
77	  async shouldStayOnLoginPage(): Promise<void> {
78	    await expectVisible(this.heading, 'Login page heading');
79	    await expectVisible(this.loginButton, 'Log in button');
80	  }
81	}
