1	import { encode } from 'z85';
2	
3	/**
4	 * Juice Shop coupon codes: the Z85 encoding of `<MMM><YY>-<NN>` (test-cases/README.md).
5	 * The server accepts a coupon only in the month it names, in the local time of the machine.
6	 */
7	const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'] as const;
8	
9	function couponText(date: Date, discountPercent: number): string {
10	  const month = MONTHS[date.getMonth()];
11	  const year = String(date.getFullYear()).slice(-2);
12	  const discount = String(discountPercent).padStart(2, '0');
13	  return `${month}${year}-${discount}`;
14	}
15	
16	function encodeCoupon(text: string): string {
17	  const code = encode(text);
18	  if (!code) {
19	    throw new Error(`z85 cannot encode the coupon text "${text}"`);
20	  }
21	  return code;
22	}
23	
24	export class CouponHelper {
25	  static currentMonthCoupon(discountPercent: number): string {
26	    return encodeCoupon(couponText(new Date(), discountPercent));
27	  }
28	
29	  static previousMonthCoupon(discountPercent: number): string {
30	    const now = new Date();
31	    const previousMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
32	    return encodeCoupon(couponText(previousMonth, discountPercent));
33	  }
34	}
