import type { Locator, Page } from '@playwright/test';

const READ_ONLY_METHOD = 'GET';

export abstract class BaseComponent {
  constructor(protected readonly page: Page) {}

  /**
   * Clicks and waits until the app gets the response of the request that changes data.
   * GET requests to the same URL are ignored: the app often reads an item before it updates it.
   */
  protected async clickAndWaitForChange(target: Locator, urlMatcher: RegExp): Promise<void> {
    const response = this.page.waitForResponse(
      (res) => urlMatcher.test(res.url()) && res.request().method() !== READ_ONLY_METHOD,
    );
    await target.click();
    await response;
  }
}

