export abstract class BaseComponent {
  constructor(protected readonly page: Page) {}

  /** Clicks and waits until the app gets the response of the request that the click sends. */
  protected async clickAndWaitForResponse(target: Locator, urlMatcher: RegExp): Promise<void> {
    const response = this.page.waitForResponse((res) => urlMatcher.test(res.url()));
    await target.click();
    await response;
  }
}

