import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { API_RESPONSE_MATCHERS, UI_ROUTES } from '@/utils/constants/routes';
import {
  expectCount,
  expectDisabled,
  expectStaysHidden,
  expectText,
  expectUrl,
  expectVisible,
} from '@/utils/assertions/ui-assertions';
import type { BasketLine, Product } from '@/utils/types/shop';

const BASKET_URL = /\/#\/basket$/;

/** The basket page `/#/basket`. */
export class BasketPage extends BasePage {
  private readonly heading: Locator;
  private readonly rows: Locator;
  private readonly totalPrice: Locator;
  private readonly checkoutButton: Locator;

  constructor(page: Page) {
    super(page);
    this.heading = page.getByRole('heading', { name: /Your Basket/ });
    this.rows = page.locator('app-purchase-basket mat-row');
    this.totalPrice = page.locator('#price');
    this.checkoutButton = page.locator('#checkoutButton');
  }

  private row(product: Product): Locator {
    return this.rows.filter({ hasText: product.name });
  }

  private quantityCell(product: Product): Locator {
    return this.row(product).locator('.mat-column-quantity');
  }

  async open(): Promise<void> {
    await this.page.goto(UI_ROUTES.basket);
    await this.shouldSeePage();
  }

  async clickIncreaseQuantity(product: Product): Promise<void> {
    await this.clickAndWaitForResponse(this.quantityCell(product).getByRole('button').last(), API_RESPONSE_MATCHERS.basketItems);
  }

  async clickDecreaseQuantity(product: Product): Promise<void> {
    await this.clickAndWaitForResponse(this.quantityCell(product).getByRole('button').first(), API_RESPONSE_MATCHERS.basketItems);
  }

  /** Clicks the plus button until the row shows `quantity`. */
  async increaseQuantityTo(product: Product, quantity: number, currentQuantity: number): Promise<void> {
    for (let current = currentQuantity; current < quantity; current += 1) {
      await this.clickIncreaseQuantity(product);
      await this.shouldSeeQuantity(product, current + 1);
    }
  }

  async clickRemove(product: Product): Promise<void> {
    const trashButton = this.row(product).locator('.mat-column-remove').getByRole('button');
    await this.clickAndWaitForResponse(trashButton, API_RESPONSE_MATCHERS.basketItems);
  }

  async clickCheckout(): Promise<void> {
    await this.checkoutButton.click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, BASKET_URL, 'Basket page');
    await expectVisible(this.heading, 'Basket heading');
  }

  async shouldSeeLine(line: BasketLine): Promise<void> {
    const row = this.row(line.product);
    await expectVisible(row, `Basket row of ${line.product.name}`);
    await expectText(row.locator('.mat-column-product'), line.product.name, `Product name in the row of ${line.product.name}`);
    await this.shouldSeeQuantity(line.product, line.quantity);
    await expectText(row.locator('.mat-column-price'), line.product.price, `Price in the row of ${line.product.name}`);
  }

  /** The basket holds exactly these rows. */
  async shouldSeeOnlyLines(lines: BasketLine[]): Promise<void> {
    await expectCount(this.rows, lines.length, 'Basket rows');
    for (const line of lines) {
      await this.shouldSeeLine(line);
    }
  }

  async shouldSeeQuantity(product: Product, quantity: number): Promise<void> {
    await expectText(this.quantityCell(product), String(quantity), `Quantity of ${product.name}`);
  }

  /** The row shows `quantity` now and does not change during the hold window. */
  async shouldKeepQuantity(product: Product, quantity: number): Promise<void> {
    await this.shouldSeeQuantity(product, quantity);
    const otherQuantity = this.quantityCell(product).filter({ hasNotText: new RegExp(`^\\s*${quantity}\\s*$`) });
    await expectStaysHidden(otherQuantity, `Quantity of ${product.name} other than ${quantity}`);
  }

  async shouldNotSeeProduct(product: Product): Promise<void> {
    await expectCount(this.row(product), 0, `Basket rows of ${product.name}`);
    await expectStaysHidden(this.row(product), `Basket row of ${product.name}`);
  }

  async shouldSeeTotalPrice(price: string): Promise<void> {
    await expectText(this.totalPrice, `Total Price: ${price}`, 'Basket total');
  }

  async shouldSeeEmptyBasket(): Promise<void> {
    await expectCount(this.rows, 0, 'Basket rows');
  }

  async shouldSeeCheckoutDisabled(): Promise<void> {
    await expectDisabled(this.checkoutButton, 'Checkout button');
  }
}

