const productA = PRODUCTS.raspberryJuice;
const productB = PRODUCTS.eggfruitJuice;
const TOTALS = { oneOfEach: '13.98¤', twoOfProductA: '18.97¤', onlyProductB: '8.99¤' } as const;

test('Change the quantity and remove a product in the basket', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-03' },
}, async ({ api, loginPage, basketPage }) => {
  await test.step('Precondition: log in a new customer with product A and product B in the basket', async () => {
    const customer = await createCustomerWithBasket(api, [
      { product: productA, quantity: 1 },
      { product: productB, quantity: 1 },
    ]);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the basket', async () => {
    await basketPage.open();
    await basketPage.shouldSeeOnlyLines([
      { product: productA, quantity: 1 },
      { product: productB, quantity: 1 },
    ]);
    await basketPage.shouldSeeTotalPrice(TOTALS.oneOfEach);
    await basketPage.navbar.shouldSeeBasketCount(2);
  });

  await test.step('2. Click the plus button in the row of product A', async () => {
    await basketPage.clickIncreaseQuantity(productA);
    await basketPage.shouldSeeQuantity(productA, 2);
    await basketPage.shouldSeeTotalPrice(TOTALS.twoOfProductA);
    await basketPage.navbar.shouldSeeBasketCount(3);
  });

  await test.step('3. Click the minus button in the row of product A', async () => {
    await basketPage.clickDecreaseQuantity(productA);
    await basketPage.shouldSeeQuantity(productA, 1);
    await basketPage.shouldSeeTotalPrice(TOTALS.oneOfEach);
    await basketPage.navbar.shouldSeeBasketCount(2);
  });

  await test.step('4. Click the minus button in the row of product A again', async () => {
    await basketPage.clickDecreaseQuantity(productA);
    await basketPage.shouldKeepQuantity(productA, 1);
    await basketPage.shouldSeeLine({ product: productA, quantity: 1 });
    await basketPage.shouldSeeTotalPrice(TOTALS.oneOfEach);
  });

  await test.step('5. Click the trash button in the row of product A', async () => {
    await basketPage.clickRemove(productA);
    await basketPage.shouldNotSeeProduct(productA);
    await basketPage.shouldSeeOnlyLines([{ product: productB, quantity: 1 }]);
    await basketPage.shouldSeeTotalPrice(TOTALS.onlyProductB);
    await basketPage.navbar.shouldSeeBasketCount(1);
  });
});

