3	const READ_ONLY_METHOD = 'GET';
4	
5	export abstract class BaseComponent {
6	  constructor(protected readonly page: Page) {}
7	
8	  /**
9	   * Clicks and waits until the app gets the response of the request that changes data.
10	   * GET requests to the same URL are ignored: the app often reads an item before it updates it.
11	   */
12	  protected async clickAndWaitForChange(target: Locator, urlMatcher: RegExp): Promise<void> {
13	    const response = this.page.waitForResponse(
14	      (res) => urlMatcher.test(res.url()) && res.request().method() !== READ_ONLY_METHOD,
15	    );
16	    await target.click();
17	    await response;
18	  }
19	}
