2	import { DateHelper } from '@/utils/helpers/date-helper';
3	
4	/** How long an absence check watches the page before it passes (docs/core-beliefs.md, belief 3). */
5	export const ABSENCE_HOLD_MS = DateHelper.secondsToMs(2);
6	
7	export async function expectVisible(locator: Locator, description: string): Promise<void> {
8	  await expect(locator, `${description} should be visible`).toBeVisible();
9	}
10	
11	export async function expectHidden(locator: Locator, description: string): Promise<void> {
12	  await expect(locator, `${description} should be hidden`).toBeHidden();
13	}
14	
15	export async function expectText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
16	  await expect(locator, `${description} should have the text "${text}"`).toHaveText(text);
17	}
18	
19	export async function expectContainText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
20	  await expect(locator, `${description} should contain the text "${text}"`).toContainText(text);
21	}
22	
23	export async function expectTexts(locator: Locator, texts: string[], description: string): Promise<void> {
24	  await expect(locator, `${description} should have the texts ${JSON.stringify(texts)}`).toHaveText(texts);
25	}
26	
27	export async function expectUrl(page: Page, url: RegExp, description: string): Promise<void> {
28	  await expect(page, `${description} should have a URL that matches ${url}`).toHaveURL(url);
29	}
30	
31	export async function expectCount(locator: Locator, count: number, description: string): Promise<void> {
32	  await expect(locator, `${description} should have ${count} element(s)`).toHaveCount(count);
33	}
34	
35	export async function expectEnabled(locator: Locator, description: string): Promise<void> {
36	  await expect(locator, `${description} should be enabled`).toBeEnabled();
37	}
38	
39	export async function expectDisabled(locator: Locator, description: string): Promise<void> {
40	  await expect(locator, `${description} should be disabled`).toBeDisabled();
41	}
42	
43	/**
44	 * Passes only when the locator stays absent for the whole hold window.
45	 * A retrying assertion would pass on the first absent read and miss a late appearance.
46	 */
47	export async function expectStaysHidden(
48	  locator: Locator,
49	  description: string,
50	  holdMs: number = ABSENCE_HOLD_MS,
51	): Promise<void> {
52	  const appeared = await locator
53	    .first()
54	    .waitFor({ state: 'visible', timeout: holdMs })
55	    .then(() => true)
56	    .catch(() => false);
57	  expect(appeared, `${description} should not appear within ${holdMs} ms`).toBe(false);
58	}
